// Code generated by Claude (Anthropic), an AI system.
// Puts the AI model's files into this program's folder, for an on-board install that never needs the internet:
//   node tools/fetch-model.mjs            download what is missing into assets/models/<id>/resolve/main/
//   node tools/fetch-model.mjs --check    only check the files that are there (sizes from tensor-cache.json)
// Run it once on a computer with internet, then ship the folder inside the installer. The program's own server
// (serve.mjs) serves the folder, and the screen uses it before it would ever ask the public model host.
// The files are data (weights and a tokenizer); nothing downloaded is run by this tool.
import { createHash } from 'node:crypto';
import { mkdir, readFile, rename, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { AI_MODEL, publicBase } from '../src/ai-model.js';

const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
const DIR = join(ROOT, ...AI_MODEL.localDir.split('/').filter(Boolean));
const checkOnly = process.argv.includes('--check');

async function sizeOf(file) {
  try { return (await stat(file)).size; } catch { return -1; }
}

async function download(name, expected = null) {
  const file = join(DIR, name);
  const have = await sizeOf(file);
  if (have >= 0 && (expected === null || have === expected)) return { name, bytes: have, skipped: true };
  if (checkOnly) throw new Error(`${name}: ${have < 0 ? 'missing' : `${have} bytes, expected ${expected}`}`);
  const res = await fetch(publicBase() + name, { redirect: 'follow' });
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  const body = Buffer.from(await res.arrayBuffer());
  if (expected !== null && body.length !== expected) throw new Error(`${name}: got ${body.length} bytes, expected ${expected}`);
  await mkdir(dirname(file), { recursive: true });
  await writeFile(`${file}.part`, body);
  await rename(`${file}.part`, file);
  return { name, bytes: body.length, skipped: false };
}

const t0 = Date.now();
await mkdir(DIR, { recursive: true });
const done = [];
for (const name of AI_MODEL.files) done.push(await download(name));
const cache = JSON.parse(await readFile(join(DIR, 'tensor-cache.json'), 'utf8'));
const shards = (cache.records || []).map((r) => ({ name: r.dataPath, bytes: r.nbytes }));
// A few files at a time: one connection alone is often slow on a shared link.
const queue = [...shards];
const PARALLEL = Number(process.env.PARALLEL) || 6;
await Promise.all(Array.from({ length: PARALLEL }, async () => {
  for (let s = queue.shift(); s; s = queue.shift()) {
    const r = await download(s.name, s.bytes);
    done.push(r);
    if (!r.skipped) process.stdout.write(`${s.name} ${(r.bytes / 1e6).toFixed(1)} MB\n`);
  }
}));
const total = done.reduce((n, r) => n + r.bytes, 0);
const sha = async (name) => `sha256-${createHash('sha256').update(await readFile(join(DIR, name))).digest('base64')}`;
console.log(`${AI_MODEL.id}: ${done.length} files, ${(total / 1e6).toFixed(1)} MB in ${DIR} (${((Date.now() - t0) / 1000).toFixed(0)} s)`);
console.log(`mlc-chat-config.json ${await sha('mlc-chat-config.json')}`);
console.log(`tokenizer.json ${await sha('tokenizer.json')}`);
